  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const now = frame / fps;
  const voiced = Boolean(words?.length);
  const startAt = wordAt(words, "loop") ?? wordAt(words, "forward") ?? 0.2;
  const build = voiced
    ? interpolate(now, [startAt, startAt + 5], [0, 1], EASE)
    : 1;

