import {
  AbsoluteFill,
  Label,
  Plot,
  Statement,
  tokens,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  EASE_PRESETS,
} from "@decode/animation-api";

type Word = { word: string; startInSeconds: number; endInSeconds: number };

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
function wordAt(words: Word[] | undefined, token: string): number | null {
  if (!words?.length) return null;
  const hit = words.find((word) => norm(word.word) === norm(token));
  return hit ? hit.startInSeconds : null;
}

const MIN_X = 0.82;
const loss = (x: number) => 0.14 + 2.7 * Math.exp(-4.2 * x) + 0.08 * (x - MIN_X) * (x - MIN_X);
const DATA = Array.from({ length: 64 }, (_, index) => {
  const x = index / 63;
  return { x, y: loss(x) };
});

const EASE = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
  easing: EASE_PRESETS.easeInOut,
};

export default function Scene({ words }: { words?: Word[] }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const now = frame / fps;
  const voiced = Boolean(words?.length);
  const startAt = wordAt(words, "loss") ?? wordAt(words, "falls") ?? 0.3;
  const progress = voiced
    ? interpolate(now, [startAt, startAt + 3], [0, 1], EASE)
    : 1;
  const markerAt = voiced
    ? interpolate(now, [startAt + 1.2, startAt + 3], [0.05, MIN_X], EASE)
    : MIN_X;

  return (
    <AbsoluteFill style={{ background: tokens.color.surface }}>
      <Statement
        text="Loss falls, then levels off"
        words={words}
        emphasize={["falls", "levels"]}
        reveal="word"
        accent="blue"
        placement="top"
      />
      <Plot
        data={DATA}
        xDomain={[0, 1]}
        yDomain={[0, 3.2]}
        color="blue"
        progress={progress}
        markerAt={markerAt}
      />
      <Label text="Training steps" size={30} color={tokens.color.ink} region="bottom" />
      <Label text="Loss" size={30} color={tokens.color.ink} region="left" />
    </AbsoluteFill>
  );
}

