import {
  AbsoluteFill,
  Chart,
  Statement,
  tokens,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  EASE_PRESETS,
} from "@decode/animation-api";

type Word = { word: string; startInSeconds: number; endInSeconds: number };

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
function wordAt(words: Word[] | undefined, token: string): number | null {
  if (!words?.length) return null;
  const hit = words.find((word) => norm(word.word) === norm(token));
  return hit ? hit.startInSeconds : null;
}

const EPOCHS = 30;
const trainLoss = (x: number) => 0.92 * Math.exp(-x / 8) + 0.07;
const validationLoss = (x: number) => trainLoss(x) + 0.026 * Math.max(0, x - 12) * Math.max(0, x - 12) / 10;
const TRAIN = Array.from({ length: 48 }, (_, index) => {
  const x = (index / 47) * EPOCHS;
  return { x, y: trainLoss(x) };
});
const VALIDATION = Array.from({ length: 48 }, (_, index) => {
  const x = (index / 47) * EPOCHS;
  return { x, y: validationLoss(x) };
});

const EASE = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
  easing: EASE_PRESETS.easeInOut,
};

export default function Scene({ words }: { words?: Word[] }) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const now = frame / fps;
  const voiced = Boolean(words?.length);
  const startAt = wordAt(words, "curves") ?? wordAt(words, "training") ?? 0.2;
  const progress = voiced
    ? interpolate(now, [startAt, startAt + 3.2], [0, 1], EASE)
    : 1;

  return (
    <AbsoluteFill style={{ background: tokens.color.surface }}>
      <Statement
        text="When validation rises, the gap is overfitting"
        words={words}
        emphasize={["validation", "rises", "overfitting"]}
        reveal="word"
        accent="orange"
        placement="top"
      />
      <Chart
        kind="line"
        series={[
          { data: TRAIN, color: "blue", label: "Training loss" },
          { data: VALIDATION, color: "orange", label: "Validation loss" },
        ]}
        xDomain={[0, EPOCHS]}
        yDomain={[0, 1.2]}
        progress={progress}
        xAxisProgress={progress}
        yAxisProgress={progress}
        xLabel="Training steps"
        yLabel="Loss"
      />
    </AbsoluteFill>
  );
}

